import React, { useEffect, useState } from "react";
import Feedback from "./Feedback";
import Donate from "./Donate";
import Volunteer from "./Volunteer";

export default function VolunteerDonorSection({
  me,
  events,
  token,
  setMsg,
  activities
}) {
  // -------------------------------
  // STATES
  // -------------------------------
  const [achievements, setAchievements] = useState({ points: 0, level: "New" });
  const [badges, setBadges] = useState(null);
  const [myNgos, setMyNgos] = useState([]);
  const [selectedNgo, setSelectedNgo] = useState(null);

  // -------------------------------
  // LOAD USER ACHIEVEMENTS
  // -------------------------------
  useEffect(() => {
    if (!me) return;

    fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") +
        "/api/user/achievements",
      {
        headers: { Authorization: "Bearer " + token }
      }
    )
      .then((res) => res.json())
      .then((data) => {
        setAchievements({
          points: data.points || 0,
          level: data.level || "New"
        });
      })
      .catch(() => {});
  }, [me, token]);

  // -------------------------------
  // LOAD BADGES
  // -------------------------------
  useEffect(() => {
    if (!me) return;

    fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") +
        "/api/user/badges",
      {
        headers: { Authorization: "Bearer " + token }
      }
    )
      .then((res) => res.json())
      .then((data) => setBadges(data || []))
      .catch(() => {});
  }, [me, token]);

  // -------------------------------
  // LOAD NGOS THE USER IS LINKED WITH
  // -------------------------------
  useEffect(() => {
    if (!me) return;

    fetch(
      (process.env.REACT_APP_API || "http://localhost:4000") +
        "/api/user/my-ngos",
      {
        headers: { Authorization: "Bearer " + token }
      }
    )
      .then((res) => res.json())
      .then((data) => setMyNgos(data || []))
      .catch(() => {});
  }, [me, token]);

  // -------------------------------
  // HANDLERS
  // -------------------------------
  function handleNgoClick(ngo) {
    setSelectedNgo(ngo);
  }

  // -------------------------------
  // RENDER UI
  // -------------------------------
  return (
    <div className="w-full px-4 py-6">
      <h1 className="text-3xl font-bold mb-6">Volunteer/Donor Dashboard</h1>

      <div className="grid grid-cols-3 gap-6">
        {/* ---------------------------------- */}
        {/* LEFT COLUMN — ACHIEVEMENTS */}
        {/* ---------------------------------- */}
        <div className="bg-white shadow rounded-xl p-5">
          <h2 className="text-xl font-semibold mb-3">Achievements</h2>

          <div className="bg-indigo-600 text-white rounded-xl p-6 text-center mb-5">
            <div className="text-4xl font-bold">{achievements.points}</div>
            <div className="uppercase tracking-wide text-sm mt-1">Points</div>
          </div>

          <h3 className="font-semibold">Badges</h3>

          {badges === null ? (
            <p className="text-gray-500 text-sm">Loading badges...</p>
          ) : badges.length === 0 ? (
            <p className="text-gray-400 text-sm">No badges yet.</p>
          ) : (
            <div className="flex flex-wrap gap-3 mt-2">
              {badges.map((b) => (
                <div
                  key={b.id}
                  className="px-3 py-1 bg-gray-200 rounded-full text-sm"
                >
                  {b.name}
                </div>
              ))}
            </div>
          )}

          <button
            onClick={() => console.log("My NGOs clicked")}
            className="w-full mt-6 bg-gray-800 text-white px-4 py-2 rounded-lg"
          >
            My NGOs
          </button>
        </div>

        {/* ---------------------------------- */}
        {/* MIDDLE COLUMN — RECOGNITION & ACTIONS */}
        {/* ---------------------------------- */}
        <div className="bg-white shadow rounded-xl p-5">
          <h2 className="text-xl font-semibold mb-3">Recognition & Actions</h2>

          <p className="text-sm mb-4">
            <strong>Name:</strong> {me?.name || "User"} —{" "}
            <strong>Level:</strong> {achievements.level}
          </p>

          <div className="mb-5">
            <Feedback me={me} token={token} setMsg={setMsg} />
          </div>

          <div className="mb-5">
            <Donate me={me} token={token} ngos={myNgos} setMsg={setMsg} />
          </div>

          <div>
            <Volunteer events={events} me={me} token={token} />
          </div>
        </div>

        {/* ---------------------------------- */}
        {/* RIGHT COLUMN — DETAILS */}
        {/* ---------------------------------- */}
        <div className="bg-white shadow rounded-xl p-5">
          <h2 className="text-xl font-semibold mb-3">Details</h2>

          {selectedNgo ? (
            <div>
              <p className="font-semibold">{selectedNgo.name}</p>
              <p className="text-sm text-gray-600">{selectedNgo.description}</p>
            </div>
          ) : (
            <p className="text-gray-500 text-sm">
              Select an NGO from the left or actions section.
            </p>
          )}

          <div className="mt-5">
            <h3 className="font-semibold">Your NGOs</h3>
            {myNgos.length === 0 ? (
              <p className="text-gray-400 text-sm">You are not part of any NGO.</p>
            ) : (
              <ul className="mt-2 space-y-2">
                {myNgos.map((ngo) => (
                  <li
                    key={ngo.id}
                    onClick={() => handleNgoClick(ngo)}
                    className="p-2 bg-gray-100 rounded cursor-pointer hover:bg-gray-200"
                  >
                    {ngo.name}
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
